  | "wandering"
  | "seeking"
  | "gathering"
  | "waiting"
  | "eating"
  | "fleeing"
  | "startled"
  | "copying"
  | "chasing"
  | "roaming"
  | "pausing"
  | "tired"
  | "hiding";

export type DeathCause = "starved" | "old" | "contact";

export const ACTION_LABEL: Record<Action, string> = {
  wandering: "Wandering",
  seeking: "Heading for fruit",
  gathering: "Gathering at a tree",
  waiting: "Waiting for fruit",
  eating: "Eating fruit",
  fleeing: "Scooting away from red",
  startled: "Startled after a boop",
  copying: "Making a copy",
  chasing: "Chasing a blue blob",
  roaming: "Roaming",
  pausing: "Resting after a boop",
  tired: "Catching breath",
  hiding: "Hiding under the leaves",
};

interface KindConst {
  idle: number;
  move: number;
  refSpeed: number;
  vision: number;
  maxEnergy: number;
  maturity: number;
  cooldown: number;
  lifespan: [number, number];
  turn: number;
}

const KIND: Record<Kind, KindConst> = {
  blue: { idle: 0.7, move: 1.5, refSpeed: 3, vision: 0.04, maxEnergy: 170, maturity: 6, cooldown: 5, lifespan: [70, 120], turn: 7 },
  red: { idle: 0.8, move: 1.5, refSpeed: 3.5, vision: 0.035, maxEnergy: 230, maturity: 20, cooldown: 15, lifespan: [100, 170], turn: 5 },
};

export type SlotState = "ripe" | "growing" | "empty" | "eaten";

export interface FruitSlot {
  state: SlotState;
  growth: number;
  timer: number;
  eater: number;
}

export interface Tree {
  id: number;

