+      ctx.fillStyle = C.soft;
+      ctx.textAlign = "center";
+      ctx.fillText(fmtTime(t0), pad.l + 12, h - 5);
+      ctx.fillText(fmtTime(t1), pad.l + pw - 14, h - 5);
