+
+.bar-fill.blue {
+  background: linear-gradient(90deg, #8fc0ff, var(--blue));
+}
+
+.bar-fill.red {
+  background: linear-gradient(90deg, #ffa3ad, var(--red));
+}
+
+.bar-fill.timer {
+  background: linear-gradient(90deg, #ffe38a, var(--sun));
+}
+
+.bar-mark {
+  position: absolute;
+  top: -3px;
+  width: 2px;
+  height: 14px;
+  background: var(--ink);
+  border-radius: 2px;
+  opacity: 0.5;
+}
+
+.insp-energy {
+  margin: 8px 0;
+}
+
+.insp-energy .row {
+  display: flex;
+  justify-content: space-between;
+  margin-bottom: 4px;
+  font-weight: 700;
+}
+
+.insp-energy small,
+.insp-grid small {
+  color: var(--ink-soft);
+  font-weight: 700;
+}
+
+.insp-grid {
+  display: grid;
+  grid-template-columns: 78px 1fr;
+  gap: 4px 8px;
+  margin: 8px 0 0;
+}
+
+.insp-grid dt {
+  color: var(--ink-soft);
+  font-weight: 700;
+}
+
+.insp-grid dd {
+  margin: 0;
+  font-weight: 800;
+}
+
+.link {
+  border: 0;
+  background: none;
+  padding: 0;
+  color: var(--blue);
+  font-weight: 800;
+  text-decoration: underline;
+}
+
+.insp-gone {
+  margin: 10px 0 2px;
+  font-weight: 700;
+}
+
+/* ---------------------------------------------------------------- charts */
+
+.charts {
+  display: grid;
+  grid-template-columns: minmax(0, 1.65fr) minmax(0, 1fr) minmax(0, 1.15fr);
+  gap: 14px;
+  min-height: 0;
+}
+
+.card {
+  display: flex;
+  flex-direction: column;
+  min-height: 0;
+  background: var(--card);
+  backdrop-filter: blur(12px);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+  padding: 10px 12px 8px;
+}
+
+.card-head {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  margin-bottom: 4px;
+  flex-wrap: wrap;
+}
+
+.card-head h3 {
+  margin: 0;
+  font-family: Fredoka, sans-serif;
+  font-size: 15px;
+  font-weight: 600;
+}
+
+.card-head .seg {
+  margin-left: auto;
+}
+
+.card-side .card-head .seg {
+  margin-left: 0;
+}
+
+.card-note {
+  margin-left: auto;
+  color: var(--ink-soft);
+  font-weight: 700;
+  font-size: 11px;
+}
+
+.chips {
+  display: flex;
+  gap: 8px;
+  font-size: 11px;
+  font-weight: 800;
+}
+
+.chip small {
+  color: var(--ink-soft);
+  font-weight: 700;
+}
+
+.card-body {
+  position: relative;
+  flex: 1;
+  min-height: 0;
+}
+
+.card-body.scroll {
+  overflow: auto;
+}
+
+.chart-canvas {
+  position: absolute;
+  inset: 0;
+  width: 100%;
+  height: 100%;
+}
+
+.summary-head {
+  display: flex;
+  gap: 8px;
+  align-items: flex-start;
+  padding: 8px 10px;
+  border-radius: 12px;
+  background: #f4f0ff;
+}
+
+.summary-head.tone-wavy,
+.summary-head.tone-calm {
+  background: #eaf4ff;
+}
+
+.summary-head.tone-boom {
+  background: #eefbe3;
+}
+
+.summary-head.tone-small {
+  background: #f3f7e8;
+}
+
+.summary-head.tone-fade,
+.summary-head.tone-empty {
+  background: #fff0f2;
+}
+
+.summary-head p {
+  margin: 0;
+  font-weight: 800;
+  font-size: 13px;
+  line-height: 1.3;
+}
+
+.summary-emoji {
+  font-size: 18px;
+  line-height: 1;
+}
+
+.summary-lines {
+  margin: 8px 0;
+  padding-left: 18px;
+  font-size: 12px;
+  line-height: 1.4;
+  color: #5a5270;
+}
+
+.summary-lines li {
+  margin-bottom: 3px;
+}
+
+.stat-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 6px;
+}
+
+.stat-grid > div {
+  display: flex;
+  flex-direction: column;
+  padding: 6px 8px;
+  border-radius: 10px;
+  background: rgba(59, 51, 80, 0.04);
+}
+
+.stat-grid small {
+  font-size: 10px;
+  font-weight: 800;
+  text-transform: uppercase;
+  letter-spacing: 0.4px;
+  color: var(--ink-soft);
+}
+
+.stat-grid strong {
+  font-family: Fredoka, sans-serif;
+  font-size: 17px;
+  font-weight: 600;
+}
+
+.stat-grid em {
+  font-style: normal;
+  font-size: 10.5px;
+  color: var(--ink-soft);
+  font-weight: 700;
+}
+
+/* ---------------------------------------------------------------- panel */
+
+.panel {
+  min-height: 0;
+  overflow-y: auto;
+  background: var(--card);
+  backdrop-filter: blur(12px);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+  padding: 6px 14px 14px;
+  scrollbar-width: thin;
+}
+
+.panel-section {
+  padding: 12px 0;
+  border-bottom: 1px solid var(--line);
+}
+
+.panel-section:last-of-type {
+  border-bottom: 0;
+}
+
+.panel-title {
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  margin: 0 0 8px;
+  font-family: Fredoka, sans-serif;
+  font-size: 15px;
+  font-weight: 600;
+}
+
+.panel-title .dot {
+  width: 10px;
+  height: 12px;
+  border-radius: 50% 50% 45% 45%;
+}
+
+.tag {
+  margin-left: auto;
+  font-family: Nunito, sans-serif;
+  font-size: 10px;
+  font-weight: 800;
+  padding: 2px 8px;
+  border-radius: 999px;
+  background: rgba(59, 51, 80, 0.07);
+  color: var(--ink-soft);
+}
+
+.tag-live {
+  background: #e6f6dc;
+  color: #4b8d2c;
+}
+
+.presets {
+  display: grid;
+  gap: 6px;
+}
+
+.preset {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  text-align: left;
+  border: 2px solid transparent;
+  background: #fff;
+  padding: 7px 10px;
+  border-radius: 14px;
+  box-shadow: 0 2px 6px rgba(80, 60, 120, 0.07);
+  transition: transform 0.12s, border-color 0.2s;
+}
+
+.preset:hover {
+  transform: translateX(2px);
+}
+
+.preset.is-active {
+  border-color: var(--sun);
+  background: #fffbea;
+}
+
+.preset-emoji {
+  font-size: 20px;
+}
+
+.preset-text {
+  display: flex;
+  flex-direction: column;
+}
+
+.preset-text strong {
+  font-size: 13px;
+}
+
+.preset-text small {
+  font-size: 11px;
+  color: var(--ink-soft);
+  font-weight: 700;
+}
+
+.slider {
+  display: block;
+  padding: 5px 0 7px;
+}
+
+.slider-top {
+  display: flex;
+  justify-content: space-between;
+  font-size: 12.5px;
+  font-weight: 800;
+}
+
+.slider-value {
+  font-variant-numeric: tabular-nums;
+  color: var(--ink-soft);
+}
+
+.slider.is-pending .slider-value {
+  color: #c98a00;
+}
+
+.slider-hint {
+  display: block;
+  font-size: 10.5px;
+  color: var(--ink-soft);
+  font-weight: 600;
+  margin-top: 1px;
+}
+
+.slider input[type="range"] {
+  -webkit-appearance: none;
+  appearance: none;
+  width: 100%;
+  height: 8px;
+  margin: 6px 0 2px;
+  border-radius: 999px;
+  background: linear-gradient(90deg, var(--accent) 0 var(--pct), rgba(59, 51, 80, 0.1) var(--pct) 100%);
+  outline: none;
+  cursor: pointer;
+}
+
+.slider input[type="range"]::-webkit-slider-thumb {
+  -webkit-appearance: none;
+  width: 18px;
+  height: 18px;
+  border-radius: 50%;
+  background: #fff;
+  border: 3px solid var(--accent);
+  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.18);
+  transition: transform 0.12s;
+}
+
+.slider input[type="range"]::-webkit-slider-thumb:hover {
+  transform: scale(1.15);
+}
+
+.slider input[type="range"]::-moz-range-thumb {
+  width: 14px;
+  height: 14px;
+  border-radius: 50%;
+  background: #fff;
+  border: 3px solid var(--accent);
+}
+
+.btn-apply {
+  width: 100%;
+  margin-top: 6px;
+  background: #fff2c4;
+}
+
+.panel-foot {
+  margin: 8px 0 0;
+  font-size: 11px;
+  color: var(--ink-soft);
+  font-weight: 700;
+  text-align: center;
+}
+
+/* ---------------------------------------------------------------- responsive */
+
+@media (max-width: 1180px) {
+  .app {
+    height: auto;
+    grid-template-columns: 1fr;
+  }
+  .stage {
+    grid-template-rows: 62vh auto;
+  }
+  .charts {
+    grid-template-columns: 1fr 1fr;
+  }
+  .card-timeline {
+    grid-column: 1 / -1;
+    height: 260px;
+  }
+  .card-side,
+  .card-summary {
+    height: 280px;
+  }
+  .panel {
+    overflow: visible;
+  }
+  .counters {
+    margin-left: 0;
+  }
+}
+
+@media (max-width: 700px) {
+  .charts {
+    grid-template-columns: 1fr;
+  }
+  .legend-note,
+  .world-hint {
+    display: none;
+  }
+  .inspector {
+    width: auto;
+    left: 14px;
+  }
+}

success.afterFullFileContent:
:root {
  --bg1: #fdf3e7;
  --bg2: #efe6fb;
  --card: rgba(255, 255, 255, 0.82);
  --ink: #3b3350;
  --ink-soft: #8a82a0;
  --line: rgba(59, 51, 80, 0.09);
  --blue: #3f8cff;
  --red: #ff4f63;
  --fruit: #6fbf3f;
  --sun: #ffd84d;
  --radius: 20px;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 10px 30px -12px rgba(80, 60, 120, 0.25), 0 2px 6px rgba(80, 60, 120, 0.06);
  font-family: Nunito, ui-rounded, system-ui, sans-serif;
  color: var(--ink);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  height: 100%;
}

body {
  background:
    radial-gradient(1200px 700px at 15% -10%, #fff7d6 0%, transparent 60%),
    radial-gradient(900px 700px at 110% 20%, #e3dcff 0%, transparent 55%),
    linear-gradient(160deg, var(--bg1), var(--bg2));
  -webkit-font-smoothing: antialiased;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}

.app {
  height: 100vh;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 14px;
  padding: 14px;
}

/* ---------------------------------------------------------------- top bar */

.topbar {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 10px 14px;
  background: var(--card);
  backdrop-filter: blur(12px);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  flex-wrap: wrap;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand h1 {
  margin: 0;
  font-family: Fredoka, Nunito, sans-serif;
  font-weight: 600;
  font-size: 22px;
  letter-spacing: 0.2px;
}

.brand-mark {
  position: relative;
  width: 34px;
  height: 30px;
}

.brand-mark i {
  position: absolute;
  bottom: 0;
  width: 18px;
  height: 24px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
  box-shadow: inset -3px -4px 6px rgba(0, 0, 0, 0.15), inset 3px 3px 5px rgba(255, 255, 255, 0.5);
  animation: bob 1.6s ease-in-out infinite;
}

.brand-mark .b {
  left: 0;
  background: var(--blue);
}

.brand-mark .r {
  left: 15px;
  height: 20px;
  background: var(--red);
  animation-delay: -0.8s;
}

@keyframes bob {
  0%,
  100% {
    transform: translateY(0) scaleY(1);
  }
  50% {
    transform: translateY(-4px) scaleY(1.05);
  }
}

.transport {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.btn {
  border: 0;
  background: #fff;
  padding: 8px 14px;
  border-radius: 999px;
  font-weight: 800;
  font-size: 13px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 2px 8px rgba(80, 60, 120, 0.12);
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.2s;
}

.btn:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(80, 60, 120, 0.18);
}

.btn:active:not(:disabled) {
  transform: translateY(1px) scale(0.98);
}

.btn:disabled {
  opacity: 0.45;
  cursor: default;
}

.btn-play {
  background: linear-gradient(180deg, #7ad36a, #4fb84a);
  color: #fff;
  min-width: 96px;
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.15);
}

.btn-play.is-playing {
  background: linear-gradient(180deg, #ffcf5a, #f5ad2a);
}

.btn-attn {
  background: #fff2c4;
  animation: pulse 1.2s ease-in-out infinite;
}

@keyframes pulse {
  50% {
    box-shadow: 0 0 0 5px rgba(255, 216, 77, 0.35);
  }
}

.speed {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 800;
  color: var(--ink-soft);
  margin-left: 4px;
}

.seg {
  display: inline-flex;
  background: rgba(59, 51, 80, 0.06);
  border-radius: 999px;
  padding: 3px;
}

.seg button {
  border: 0;
  background: transparent;
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  color: var(--ink-soft);
}

.seg button.on {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 1px 4px rgba(80, 60, 120, 0.15);
}

.seg.small button {
  padding: 3px 9px;
  font-size: 11px;
}

.counters {
  margin-left: auto;
  display: flex;
  gap: 8px;
}

.counter {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 64px;
  padding: 4px 10px;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 2px 8px rgba(80, 60, 120, 0.08);
}

.counter b {
  font-family: Fredoka, sans-serif;
  font-size: 20px;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.counter span {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--ink-soft);
}

.c-blue,
.c-blue b {
  color: var(--blue);
}

.c-red,
.c-red b {
  color: var(--red);
}

.c-fruit,
.c-fruit b {
  color: var(--fruit);
}

/* ---------------------------------------------------------------- stage */

.stage {
  min-height: 0;
  display: grid;
  grid-template-rows: minmax(0, 1fr) 262px;
  gap: 14px;
}

.world-card {
  position: relative;
  min-height: 0;
  border-radius: var(--radius);
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 35%, rgba(255, 255, 255, 0.9), rgba(255, 255, 255, 0) 70%),
    linear-gradient(180deg, #dff1ff 0%, #f6ecff 60%, #ffe9dc 100%);
  box-shadow: var(--shadow);
}

.world {
  position: absolute;
  inset: 0;
}

.world canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
}

.world canvas:active {
  cursor: grabbing;
}

.world-hint {
  position: absolute;
  top: 12px;
  left: 14px;
  font-size: 12px;
  font-weight: 700;
  color: var(--ink-soft);
  background: rgba(255, 255, 255, 0.7);
  padding: 5px 10px;
  border-radius: 999px;
  pointer-events: none;
}

.world-toggles {
  position: absolute;
  bottom: 12px;
  right: 14px;
  display: flex;
  gap: 8px;
}

.toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 800;
  background: rgba(255, 255, 255, 0.8);
  padding: 5px 10px 5px 6px;
  border-radius: 999px;
  cursor: pointer;
  user-select: none;
}

.toggle input {
  appearance: none;
  width: 26px;
  height: 15px;
  border-radius: 999px;
  background: rgba(59, 51, 80, 0.18);
  position: relative;
  margin: 0;
  cursor: pointer;
  transition: background 0.2s;
}

.toggle input::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.2s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.toggle input:checked {
  background: var(--fruit);
}

.toggle input:checked::after {
  transform: translateX(11px);
}

.toggle.small {
  background: rgba(59, 51, 80, 0.05);
  margin-top: 8px;
}

.legend {
  position: absolute;
  bottom: 12px;
  left: 14px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  font-size: 12px;
  font-weight: 800;
  background: rgba(255, 255, 255, 0.8);
  padding: 6px 12px;
  border-radius: 999px;
  pointer-events: none;
}

.legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.legend i {
  display: inline-block;
  width: 10px;
  height: 12px;
  border-radius: 50% 50% 45% 45%;
}

.lg-fruit {
  background: #b8f24c;
  border-radius: 50% !important;
  width: 10px !important;
  height: 10px !important;
}

.lg-blue {
  background: var(--blue);
}

.lg-red {
  background: var(--red);
}

.legend-note {
  color: var(--ink-soft);
}

.big-play {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  border: 0;
  padding: 14px 26px;
  border-radius: 999px;
  font-family: Fredoka, sans-serif;
  font-size: 20px;
  font-weight: 600;
  color: #fff;
  background: linear-gradient(180deg, #7ad36a, #4fb84a);
  box-shadow: 0 12px 30px -8px rgba(60, 140, 60, 0.6), 0 0 0 6px rgba(255, 255, 255, 0.55);
  animation: float 2.4s ease-in-out infinite;
}

@keyframes float {
  50% {
    transform: translate(-50%, calc(-50% - 6px));
  }
}

/* ---------------------------------------------------------------- inspector */

.inspector {
  position: absolute;
  top: 12px;
  right: 14px;
  width: 270px;
  padding: 12px 14px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(10px);
  box-shadow: 0 16px 40px -14px rgba(60, 40, 110, 0.45);
  font-size: 12.5px;
  animation: pop 0.22s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.inspector.blue {
  border-top: 4px solid var(--blue);
}

.inspector.red {
  border-top: 4px solid var(--red);
}

@keyframes pop {
  from {
    transform: scale(0.9);
    opacity: 0;
  }
}

.insp-head {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: Fredoka, sans-serif;
  font-size: 15px;
}

.insp-head .icon-btn {
  margin-left: auto;
}

.insp-dot {
  width: 12px;
  height: 15px;
  border-radius: 50% 50% 45% 45%;
}

.insp-dot.blue {
  background: var(--blue);
}

.insp-dot.red {
  background: var(--red);
}

.badge {
  font-family: Nunito, sans-serif;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgba(59, 51, 80, 0.08);
}

.badge.soft {
  background: #e6f6dc;
  color: #4b8d2c;
}

.icon-btn {
  border: 0;
  background: rgba(59, 51, 80, 0.06);
  width: 24px;
  height: 24px;
  border-radius: 50%;
  font-size: 11px;
}

.insp-action {
  margin: 8px 0 4px;
  display: flex;
  gap: 6px;
  align-items: center;
  font-weight: 800;
  font-size: 13px;
}

.insp-timer {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.insp-timer .bar {
  flex: 1;
}

.insp-timer small {
  color: var(--ink-soft);
  font-weight: 700;
  min-width: 50px;
  text-align: right;
}

.bar {
  position: relative;
  height: 8px;
  border-radius: 999px;
  background: rgba(59, 51, 80, 0.08);
  overflow: visible;
}

.bar-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.15s linear;
}

.bar-fill.blue {
