      ctx.fillText(String(ym), pad.l - 5, pad.t + 8);
      ctx.fillText("0", pad.l - 5, pad.t + ph);
      ctx.fillStyle = C.blue;
      ctx.textAlign = "right";
      ctx.fillText(`${xm} blue →`, pad.l + pw, h - 6);
      ctx.save();
      ctx.translate(10, pad.t + ph / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.textAlign = "center";
